using Microsoft.AspNetCore.Hosting;
using TutorFlow.Infrastructure.Configuracion;

namespace TutorFlow.Api;

internal sealed partial class ValidacionDeArranque : IStartupFilter
{
    private static readonly string[] VariablesDePrecio = ["LLM_PRECIO_ENTRADA", "LLM_PRECIO_SALIDA"];

    private readonly IConfiguration _configuracion;
    private readonly IVariablesEntorno _variables;
    private readonly ILogger _logger;

    public ValidacionDeArranque(IConfiguration configuracion, IVariablesEntorno variables, ILoggerFactory fabricaDeLogs)
    {
        _configuracion = configuracion;
        _variables = variables;
        _logger = fabricaDeLogs.CreateLogger("TutorFlow.Configuracion");
    }

    public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> siguiente)
    {
        var efectiva = ConEntorno();
        var errores = ValidadorDeConfiguracion.Validar(efectiva);
        if (errores.Count > 0)
        {
            throw new InvalidOperationException(string.Join("\n", errores));
        }

        foreach (var advertencia in ValidadorDeConfiguracion.Advertencias(efectiva))
        {
            RegistrarAdvertencia(_logger, advertencia);
        }

        return siguiente;
    }

    private IConfiguration ConEntorno()
    {
        var delEntorno = VariablesDePrecio
            .Select(nombre => new KeyValuePair<string, string?>(nombre, _variables.Leer(nombre)))
            .Where(par => par.Value is not null);
        return new ConfigurationBuilder().AddConfiguration(_configuracion).AddInMemoryCollection(delEntorno).Build();
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "{Mensaje}")]
    internal static partial void RegistrarAdvertencia(ILogger logger, string mensaje);
}
    private const int PuntajeRelativoRelevantePorDefecto = 40;
    private const string ClaveTemperatura = "Llm:Temperatura";
    private const string ClaveSemilla = "Llm:Semilla";
    private const int SemillaPorDefecto = 1;
    private const string ClaveSeccionLimites = "Limites";
    private const string ClaveTraceId = "traceId";
    private const string VariableLlaveLlm = "LLM_API_KEY";

    public static IServiceCollection AgregarTutorFlow(this IServiceCollection servicios, IConfiguration configuracion)
    {
        servicios.AddTransient<IStartupFilter, ValidacionDeArranque>();
        AgregarOpciones(servicios);
        AgregarNucleo(servicios, configuracion);
        AgregarInfraestructura(servicios, configuracion);
        AgregarLlm(servicios, configuracion);
        servicios.AddProblemDetails(opciones =>
            opciones.CustomizeProblemDetails = contexto => contexto.ProblemDetails.Extensions[ClaveTraceId] = contexto.HttpContext.TraceIdentifier);
        servicios.AddExceptionHandler<ManejadorExcepciones>();
        servicios.ConfigureHttpJsonOptions(opciones => opciones.SerializerOptions.Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping);
        servicios.AddHostedService<RegistroArranqueLlm>();
        return servicios;
    }

    private static void AgregarOpciones(IServiceCollection servicios)
    {
        servicios.AddOptions<OpcionesApiAcademica>()
            .BindConfiguration(OpcionesApiAcademica.Seccion)
